import React, { useState } from 'react';

function ProductsSection({ 
  products, 
  cart, 
  onAddToCart, 
  onRemoveFromCart, 
  onClearCart,
  isCartOpen = false,
  onOpenCart,
  onCloseCart,
  showAlert 
}) {
  const [activeCategory, setActiveCategory] = useState('all');
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedQuality, setSelectedQuality] = useState('Deluxe');
  const [selectedSize, setSelectedSize] = useState('A3 Wall Mount');
  const [optionsModalOpen, setOptionsModalOpen] = useState(false);
  const [internalCartOpen, setInternalCartOpen] = useState(false);
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);

  // Single-column slider indexes for Row 1 (Daily), Row 2 (Monthly), Row 3 (Specialty)
  const [dailyIndex, setDailyIndex] = useState(0);
  const [monthlyIndex, setMonthlyIndex] = useState(0);
  const [specialtyIndex, setSpecialtyIndex] = useState(0);

  // Payment Form State
  const [payName, setPayName] = useState('');
  const [payEmail, setPayEmail] = useState('');
  const [payMobile, setPayMobile] = useState('');
  const [payAddress, setPayAddress] = useState('');
  const [payMethod, setPayMethod] = useState('gpay');
  const [qrGenerated, setQrGenerated] = useState(false);

  // Cart open state controlled externally or internally
  const cartOpen = isCartOpen || internalCartOpen;

  const handleCloseCartDrawer = () => {
    setInternalCartOpen(false);
    if (onCloseCart) onCloseCart();
  };

  const handleOpenCartDrawer = () => {
    if (onOpenCart) onOpenCart();
    setInternalCartOpen(true);
  };

  // Quality multiplier map
  const qualityPriceMultiplier = {
    'Standard': 1.0,
    'Deluxe': 1.2,
    'Premium Gold': 1.5
  };

  const handleOpenOptions = (product) => {
    setSelectedProduct(product);
    setSelectedQuality('Deluxe');
    setSelectedSize('A3 Wall Mount');
    setOptionsModalOpen(true);
  };

  const handleConfirmAddToCart = () => {
    if (!selectedProduct) return;

    const basePrice = selectedProduct.price;
    const finalPrice = Math.round(basePrice * (qualityPriceMultiplier[selectedQuality] || 1.0));

    const cartItem = {
      id: Date.now() + Math.random(),
      productId: selectedProduct.id,
      name: selectedProduct.name,
      category: selectedProduct.category,
      image: selectedProduct.image,
      quality: selectedQuality,
      size: selectedSize,
      price: finalPrice
    };

    onAddToCart(cartItem);
    setOptionsModalOpen(false);
    showAlert(`${selectedProduct.name} (${selectedQuality}, ${selectedSize}) added to cart!`, 'success');
  };

  const cartTotal = cart.reduce((acc, item) => acc + item.price, 0);

  // Split products by category for 3 explicit rows
  const dailyProducts = products.filter(p => p.category === 'daily');
  const monthlyProducts = products.filter(p => p.category === 'monthly');
  const specialtyProducts = products.filter(p => p.category === 'specialty');

  const handleProceedPayment = (e) => {
    e.preventDefault();
    if (cart.length === 0) {
      showAlert("Your cart is empty!", "warning");
      return;
    }
    if (!payName.trim() || !payMobile.trim() || !payAddress.trim()) {
      showAlert("Please fill in all delivery details.", "error");
      return;
    }
    setQrGenerated(true);
    showAlert("Payment QR Code generated successfully!", "success");
  };

  const handleCompleteOrder = () => {
    onClearCart();
    setPaymentModalOpen(false);
    handleCloseCartDrawer();
    setQrGenerated(false);
    setPayName('');
    setPayEmail('');
    setPayMobile('');
    setPayAddress('');
    showAlert("Order placed successfully! Thank you for choosing Karpagam Traders.", "success");
  };

  // Render individual product card UI mockup (image_a918e0 / image_a9193a)
  const renderProductCard = (product, isSideBlur = false) => {
    if (!product) return null;
    const badgeLabel = product.category === 'daily' ? 'DAILY' : product.category === 'monthly' ? 'MONTHLY' : 'SPECIALTY';
    return (
      <div key={product.id} id={`prod-card-${product.id}`} className={`product-card-item exact-mockup-card scroll-reveal-fade revealed ${isSideBlur ? 'blur-card' : ''}`}>
        <div className="product-image-container">
          <span className="image-dark-red-badge">{badgeLabel}</span>

          <img 
            src={product.image} 
            alt={product.name} 
            className="product-card-img"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = 'https://images.unsplash.com/photo-1506784983877-45594efa4cbe?w=500&auto=format&fit=crop';
            }}
          />

          {/* Centered White Pill Overlay Button */}
          <div className="image-overlay-action">
            <button className="btn-quick-view" onClick={() => handleOpenOptions(product)}>
              <i className="fa-solid fa-eye" style={{ color: '#8b0000' }}></i> View Options
            </button>
          </div>
        </div>

        <div className="product-card-details">
          <h3 className="product-title">{product.name}</h3>
          <p className="product-desc">{product.description || 'Standard daily tear-off sheet calendar with auspicious Nalla Neram.'}</p>

          {/* Subtle Horizontal Divider Line */}
          <div className="product-card-divider"></div>

          <div className="product-card-footer">
            <div className="product-price-box">
              <span className="price-label">PRICE</span>
              <span className="price-value">₹{product.price}</span>
            </div>

            <button className="btn-add-cart dark-red-pill-btn" onClick={() => handleOpenOptions(product)} title="Add to Cart">
              <i className="fa-solid fa-cart-plus"></i> Add
            </button>
          </div>
        </div>
      </div>
    );
  };

  // Render Section Row (Desktop 4-Column Grid + Mobile Coverflow Carousel Slider)
  const renderCategoryRow = (list, currIndex, setIndex, rowTitle, categoryIcon, rowBadgeLabel, rowNumber) => {
    if (!list || list.length === 0) return null;
    const len = list.length;
    const prevItem = list[(currIndex - 1 + len) % len];
    const currItem = list[currIndex % len];
    const nextItem = list[(currIndex + 1) % len];

    const handlePrev = () => setIndex(prev => (prev === 0 ? len - 1 : prev - 1));
    const handleNext = () => setIndex(prev => (prev === len - 1 ? 0 : prev + 1));

    return (
      <div className="product-category-row-section">
        <div className="row-category-header">
          <h3 className="dark-red-title">
            <i className={`fa-solid ${categoryIcon}`}></i> Row {rowNumber}: {rowTitle}
          </h3>
          <span className="dark-red-badge-pill">{rowBadgeLabel} {currIndex + 1} of {len}</span>
        </div>

        {/* Desktop 4-Column Responsive Grid Layout (side-by-side repeat(4, 1fr)) */}
        <div className="desktop-4col-grid">
          {list.map(product => renderProductCard(product, false))}
        </div>

        {/* Mobile Coverflow Carousel View */}
        <div className="coverflow-3card-wrapper">
          <button className="row-outer-nav-btn left-nav" onClick={handlePrev} title="Previous Product">
            <i className="fa-solid fa-chevron-left"></i>
          </button>

          <div className="side-card-blur left-blur">
            {renderProductCard(prevItem, true)}
          </div>

          <div className="center-card-main">
            {renderProductCard(currItem, false)}
          </div>

          <div className="side-card-blur right-blur">
            {renderProductCard(nextItem, true)}
          </div>

          <button className="row-outer-nav-btn right-nav" onClick={handleNext} title="Next Product">
            <i className="fa-solid fa-chevron-right"></i>
          </button>
        </div>
      </div>
    );
  };

  return (
    <section id="shop-section" className="products-shop-wrapper">
      <div className="section-title scroll-reveal-fade revealed">
        <h2>Daily & Monthly Calendar Shop</h2>
        <p>Explore our exclusive Sivakasi offset printed tear-off daily sheets, monthly wall designs, and custom diaries</p>
      </div>

      {/* Category Filter Pills */}
      <div className="category-filter-bar">
        <button 
          className={`filter-pill ${activeCategory === 'all' ? 'active' : ''}`}
          onClick={() => setActiveCategory('all')}
        >
          <i className="fa-solid fa-layer-group"></i> All Calendars ({products.length})
        </button>
        <button 
          className={`filter-pill ${activeCategory === 'daily' ? 'active' : ''}`}
          onClick={() => setActiveCategory('daily')}
        >
          <i className="fa-solid fa-calendar-day"></i> Daily Tear-Offs ({dailyProducts.length})
        </button>
        <button 
          className={`filter-pill ${activeCategory === 'monthly' ? 'active' : ''}`}
          onClick={() => setActiveCategory('monthly')}
        >
          <i className="fa-solid fa-calendar-days"></i> Monthly Wall ({monthlyProducts.length})
        </button>
        <button 
          className={`filter-pill ${activeCategory === 'specialty' ? 'active' : ''}`}
          onClick={() => setActiveCategory('specialty')}
        >
          <i className="fa-solid fa-star"></i> Cake & Specialty ({specialtyProducts.length})
        </button>

        {/* View Cart Button */}
        <button className="cart-trigger-btn" onClick={handleOpenCartDrawer}>
          <i className="fa-solid fa-cart-shopping"></i>
          <span>View Cart</span>
          <span className="cart-badge-count">{cart.length}</span>
        </button>
      </div>

      {/* 3 CATEGORIZED ROWS */}
      <div className="categorized-rows-container">
        {/* ROW 1: DAILY TEAR-OFF CALENDARS */}
        {(activeCategory === 'all' || activeCategory === 'daily') && (
          renderCategoryRow(
            dailyProducts, 
            dailyIndex, 
            setDailyIndex, 
            "Daily Tear-Off Calendars", 
            "fa-calendar-day", 
            "Daily",
            1
          )
        )}

        {/* ROW 2: MONTHLY WALL CALENDARS */}
        {(activeCategory === 'all' || activeCategory === 'monthly') && (
          renderCategoryRow(
            monthlyProducts, 
            monthlyIndex, 
            setMonthlyIndex, 
            "Monthly Wall Calendars", 
            "fa-calendar-days", 
            "Monthly",
            2
          )
        )}

        {/* ROW 3: CAKE & SPECIALTY CALENDARS */}
        {(activeCategory === 'all' || activeCategory === 'specialty') && (
          renderCategoryRow(
            specialtyProducts, 
            specialtyIndex, 
            setSpecialtyIndex, 
            "Cake & Specialty Calendars", 
            "fa-cake-candles", 
            "Specialty",
            3
          )
        )}
      </div>

      {/* PRODUCT OPTIONS MODAL (CONVERTED TO HTML SELECT DROPDOWN LISTS) */}
      {optionsModalOpen && selectedProduct && (
        <div className="product-modal-overlay">
          <div className="product-modal-card">
            <button className="close-modal-btn" onClick={() => setOptionsModalOpen(false)} title="Close Options">
              <i className="fa-solid fa-xmark"></i>
            </button>

            <div className="modal-content-grid">
              <div className="modal-img-col">
                <img src={selectedProduct.image} alt={selectedProduct.name} className="modal-product-img" />
              </div>

              <div className="modal-details-col">
                <span className="modal-cat-tag">{selectedProduct.category.toUpperCase()}</span>
                <h2 className="modal-product-title">{selectedProduct.name}</h2>
                <p className="modal-product-desc">{selectedProduct.description || 'Premium Sivakasi print on high-gsm paper with gold foil title and clear daily typography.'}</p>

                {/* Option 1: Paper Quality Dropdown Select */}
                <div className="option-section">
                  <label className="option-label">Paper Quality Grade:</label>
                  <select 
                    className="modal-select-dropdown"
                    value={selectedQuality}
                    onChange={(e) => setSelectedQuality(e.target.value)}
                  >
                    <option value="Standard">Standard (Base Price)</option>
                    <option value="Deluxe">Deluxe (+20% High GSM)</option>
                    <option value="Premium Gold">Premium Gold (+50% Foil Finish)</option>
                  </select>
                </div>

                {/* Option 2: Calendar Dimensions / Size Dropdown Select */}
                <div className="option-section">
                  <label className="option-label">Calendar Dimensions & Style:</label>
                  <select 
                    className="modal-select-dropdown"
                    value={selectedSize}
                    onChange={(e) => setSelectedSize(e.target.value)}
                  >
                    <option value="A3 Wall Mount">A3 Wall Mount (Standard)</option>
                    <option value="A4 Desk Stand">A4 Desk Stand</option>
                    <option value="Compact Tear-Off">Compact Tear-Off</option>
                  </select>
                </div>

                <div className="modal-price-footer">
                  <div className="calculated-price">
                    <span className="lbl">Calculated Price:</span>
                    <span className="val">₹{Math.round(selectedProduct.price * (qualityPriceMultiplier[selectedQuality] || 1.0))}</span>
                  </div>

                  <button className="btn-modal-add-cart" onClick={handleConfirmAddToCart}>
                    <i className="fa-solid fa-cart-plus"></i> Add to Cart
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* SHOPPING CART RIGHT DRAWER OVERLAY */}
      {cartOpen && (
        <div className="cart-drawer-overlay" onClick={handleCloseCartDrawer}>
          <div className="cart-drawer-card" onClick={(e) => e.stopPropagation()}>
            <div className="cart-drawer-header">
              <h3><i className="fa-solid fa-basket-shopping"></i> Shopping Cart ({cart.length})</h3>
              <button className="close-drawer-btn" onClick={handleCloseCartDrawer}>
                <i className="fa-solid fa-xmark"></i>
              </button>
            </div>

            <div className="cart-drawer-body">
              {cart.map((item, idx) => (
                <div key={idx} className="cart-item-card">
                  <img src={item.image} alt={item.name} className="cart-item-img" />
                  <div className="cart-item-info">
                    <h4>{item.name}</h4>
                    <p className="item-specs">{item.quality} • {item.size}</p>
                    <span className="item-price">₹{item.price}</span>
                  </div>
                  <button className="remove-item-btn" onClick={() => onRemoveFromCart(idx)} title="Remove Item">
                    <i className="fa-solid fa-trash-can"></i>
                  </button>
                </div>
              ))}

              {cart.length === 0 && (
                <div className="empty-cart-view">
                  <i className="fa-solid fa-cart-flatbed"></i>
                  <p>Your shopping cart is currently empty.</p>
                </div>
              )}
            </div>

            {cart.length > 0 && (
              <div className="cart-drawer-footer">
                <div className="cart-summary-line">
                  <span>Total Amount:</span>
                  <span className="total-val">₹{cartTotal}</span>
                </div>

                <div className="cart-action-buttons">
                  <button className="btn-clear-cart" onClick={onClearCart}>
                    Clear All
                  </button>
                  <button className="btn-checkout" onClick={() => {
                    handleCloseCartDrawer();
                    setPaymentModalOpen(true);
                  }}>
                    <i className="fa-solid fa-shield-check"></i> Checkout
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* UPI QR PAYMENT MODAL */}
      {paymentModalOpen && (
        <div className="product-modal-overlay">
          <div className="product-modal-card payment-modal-card">
            <button className="close-modal-btn" onClick={() => {
              setPaymentModalOpen(false);
              setQrGenerated(false);
            }}>
              <i className="fa-solid fa-xmark"></i>
            </button>

            <div className="payment-modal-header">
              <h3><i className="fa-solid fa-qrcode"></i> Express Checkout & UPI Payment</h3>
              <p>Scan & Pay using Google Pay, PhonePe, Paytm, or BHIM UPI</p>
            </div>

            <div className="payment-modal-body">
              {!qrGenerated ? (
                <form onSubmit={handleProceedPayment} className="delivery-form-grid">
                  <div className="form-group-full">
                    <label>Full Name *</label>
                    <input 
                      type="text" 
                      required 
                      placeholder="e.g. Full Name" 
                      value={payName}
                      onChange={(e) => setPayName(e.target.value)}
                    />
                  </div>

                  <div className="form-group-half">
                    <label>Mobile Number *</label>
                    <input 
                      type="tel" 
                      required 
                      placeholder="+91 94432 10987" 
                      value={payMobile}
                      onChange={(e) => setPayMobile(e.target.value)}
                    />
                  </div>

                  <div className="form-group-half">
                    <label>Email Address</label>
                    <input 
                      type="email" 
                      placeholder="customer@example.com" 
                      value={payEmail}
                      onChange={(e) => setPayEmail(e.target.value)}
                    />
                  </div>

                  <div className="form-group-full">
                    <label>Delivery Address *</label>
                    <textarea 
                      rows="2" 
                      required 
                      placeholder="Door No, Street Name, City, Pincode" 
                      value={payAddress}
                      onChange={(e) => setPayAddress(e.target.value)}
                    ></textarea>
                  </div>

                  <div className="form-group-full">
                    <label>Preferred Payment Method:</label>
                    <div className="payment-methods-row">
                      <label className={`pay-method-pill ${payMethod === 'gpay' ? 'active' : ''}`}>
                        <input type="radio" name="pay" value="gpay" checked={payMethod === 'gpay'} onChange={() => setPayMethod('gpay')} />
                        <i className="fa-brands fa-google-pay"></i> Google Pay
                      </label>
                      <label className={`pay-method-pill ${payMethod === 'phonepe' ? 'active' : ''}`}>
                        <input type="radio" name="pay" value="phonepe" checked={payMethod === 'phonepe'} onChange={() => setPayMethod('phonepe')} />
                        <i className="fa-solid fa-mobile-screen"></i> PhonePe UPI
                      </label>
                      <label className={`pay-method-pill ${payMethod === 'paytm' ? 'active' : ''}`}>
                        <input type="radio" name="pay" value="paytm" checked={payMethod === 'paytm'} onChange={() => setPayMethod('paytm')} />
                        <i className="fa-solid fa-wallet"></i> Paytm / UPI
                      </label>
                    </div>
                  </div>

                  <div className="payment-summary-box">
                    <div className="summary-line">
                      <span>Total Printable Items:</span>
                      <strong>{cart.length} Products</strong>
                    </div>
                    <div className="summary-line grand">
                      <span>Grand Total:</span>
                      <strong className="grand-price">₹{cartTotal}</strong>
                    </div>
                  </div>

                  <button type="submit" className="btn-generate-qr">
                    <i className="fa-solid fa-qrcode"></i> Generate Payment QR Code
                  </button>
                </form>
              ) : (
                <div className="qr-code-display-wrapper">
                  <div className="qr-box">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(`upi://pay?pa=9566801402@ybl&pn=KarpagamTraders&am=${cartTotal}&cu=INR`)}`} 
                      alt="Karpagam Traders UPI QR Code" 
                      className="generated-qr-img"
                    />
                    <span className="upi-id-tag">UPI ID: 9566801402@ybl</span>
                  </div>

                  <div className="qr-instructions">
                    <h4>Scan to Pay ₹{cartTotal}</h4>
                    <p>Open Google Pay, PhonePe, Paytm, or any UPI app to scan and complete the transaction.</p>
                  </div>

                  <button className="btn-complete-order" onClick={handleCompleteOrder}>
                    <i className="fa-solid fa-circle-check"></i> Complete & Submit Order
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

export default ProductsSection;
